/**
 * Constants shared between the CMS (apps/cms) and the web frontend (apps/web).
 */

/** Collection slugs exposed over the REST API and consumed by the frontend. */
export const COLLECTION_SLUGS = {
  pages: 'pages',
  posts: 'posts',
  projects: 'projects',
  media: 'media',
  categories: 'categories',
  search: 'search',
  redirects: 'redirects',
  forms: 'forms',
  formSubmissions: 'form-submissions',
} as const

/** Image rendition names generated by the Media collection (sharp-era uploads). */
export const IMAGE_SIZES = [
  'thumbnail',
  'square',
  'small',
  'medium',
  'large',
  'xlarge',
  'og',
] as const

/** Name of the HttpOnly cookie that enables draft-content fetching on the web app. */
export const DRAFT_COOKIE = 'athena-draft'

/** Cache-tag names used for KV version stamps in the web app's cache layer. */
export const CACHE_TAGS = {
  pages: 'pages',
  posts: 'posts',
  projects: 'projects',
  site: 'global_site',
  header: 'global_header',
  footer: 'global_footer',
  stack: 'global_stack',
  redirects: 'redirects',
  sitemap: 'sitemap',
} as const

export type CacheTag = (typeof CACHE_TAGS)[keyof typeof CACHE_TAGS]

/**
 * Content locales. English is the default (unprefixed URLs, Payload's
 * `defaultLocale`); Japanese and Simplified Chinese live under `/ja` and `/zh`
 * and fall back to English field by field until translated.
 */
export const LOCALES = ['en', 'ja', 'zh'] as const
export type Locale = (typeof LOCALES)[number]
export const DEFAULT_LOCALE: Locale = 'en'

/**
 * Public URL paths of the web app's sections (without a locale prefix). The
 * CMS uses them for invalidation and draft preview; the web app for routes,
 * links, feeds and sitemaps.
 */
export const ROUTES = {
  /** Posts collection: list, `/notes/page/<n>` and `/notes/<slug>`. */
  posts: '/notes',
  /** Projects collection: list and `/builds/<repo>`. */
  work: '/builds',
  /** Stack global. */
  stack: '/stacks',
} as const

/** Section paths used before 1.2.0, each permanently redirected to its route. */
export const LEGACY_ROUTES: Record<string, string> = {
  '/posts': ROUTES.posts,
  '/work': ROUTES.work,
  '/stack': ROUTES.stack,
}

/**
 * Maps an old section path (`/posts/x`, `/work`, `/stack`) to its current
 * route; any other path comes back unchanged. Keeps links typed in the CMS
 * before the rename pointing at the right page without a redirect.
 */
export const currentRoute = (path: string): string => {
  const match = /^(\/[^/?#]+)(.*)$/.exec(path)
  const next = match?.[1] ? LEGACY_ROUTES[match[1]] : undefined
  return next ? `${next}${match?.[2] ?? ''}` : path
}
